; >S:EDIT-JIGSAW; PUT "EDIT-JIGSAW";; CALLED WHEN THA BASIC LOOP IS; IN CONTROL;EDIT;LDA #0STA JIGXSTA JIGYSTA SWAP;RELESO;JSR CHKSPC ;* SPACE STATUSBCS RELESO ;* RELEASE SPACE;EDJIG1;LDX #$30JSR DELAY+2;JSR CHKSPC ;* SPACE TO RETURNBCC CARYON;YESFAB;JSR CHKSPC ;* PLEASE RELEASE IT !BCS YESFAB;JSR COLJIG ;* TIDY UP COLOUR;RTS;CARYON;JSR JIGGY  ;* MOVE THE CURSOR;BIT JFIRE  ;* FIRE TO COPY ?BPL EDJIG1;LDA SWAP   ;* SECOND TIME HEREBNE PLACE  ;* SO NOW COPY IT;LDA SLSTA COPYLLDA SL+1STA COPYL+1;; SAVE ADDRESS;LDY #0LDA (SL),Y ;* COPY CHARSTA COPYCHSTA $E01+80;LDA #1STA SWAP;BNE EDJIG1;PLACE;; SECOND TIME THAT FIRE IS; PRESSED SO LETS SWAP IT;LDY #0LDA (SL),Y     ;* CURRENT CHAR;STA (COPYL),Y  ;* SWOP IT;LDA COPYCH     ;* REPLACE CHARSTA (SL),Y     ;* PUT IT ON;LDA #0STA SWAPLDA #37STA $E01+80;JMP EDJIG1;;;-++++++++++++++++++++++++++++-;JIGGY;; MOVE THE CURSOR ABOUT;LDX JIGXLDY JIGY;BIT JLEFTBPL LENO;CPX #0BEQ LENO    ;* AT LEFT;DEX;LENO;BIT JRIGHTBPL RINO;CPX #4BEQ RINO    ;* AT RIGHT;INX;RINO;BIT JUPBPL UPNO;CPY #0BEQ UPNO    ;*  AT TOP;DEY;UPNO;BIT JDOWNBPL DONO;CPY #4BEQ DONO    ;* AT BOTTOM;INY;DONO;STX JIGXSTY JIGYJSR JIGXY;JSR COLJIG  ;* COLOUR THE JIGSAW;LDA TEDAND #%11110111 ;* RND COLOUR;LDY #0STA (CL),Y  ;* COLOUR EDIT SQUARE;RTS;;--------------------------------;JIGXY;; ADD OFFSETS;TXACLCADC #34TAX;TYACLCADC #12TAY;JSR XY;RTS;;********************************;COLJIG;; COLOUR THE JIGSAW WITH THE; FOLLOWING RULES:-;; 1) IF PIECE OF JIGSAW BUT IN;    WRONG PLACE THEN LUM=$40;; 2) IF NOT A PIECE OF JIGSAW;    THEN LUM=$10;; 3) IF PIECE OF JIIGSAW AND IN;    RIGHT PLACE THEN LUM=$70;;LDX #0STX NOCORR;LDA #215STA JIGNO      ;* START JIG CHAR;CJIG1;LDY RADY,XLDA $E02,Y     ;* GET CHAR;CMP #27        ;* EMPTY JIG CHARBNE NOEMP;LDA #$64BNE COLIT;NOEMP;CMP JIGNO      ;* CORRECY CHAR ?BNE NOCOR;INC NOCORR     ;* ANOTHER CORRECT;LDA #$71BNE COLIT;NOCOR;LDA #$10;COLIT;STA $A02,Y     ;* COLOUR ON;INC JIGNO      ;* NEXT PIECE;INXCPX #25;BNE CJIG1      ;* DO FULL GRID;LDA NOCORR     ;* # IN CORRECTCMP #25;BNE NTFIND;; WELL DONW HE'S COMPLETED THIS; LEVEL;JMP UPLEVL;NTFIND;RTS;;********************************;PRJIG;; PRINT INITIAL JIGSAW;LDX #24;LDA #239STA CHAR;PRJIG1;LDY RADY,X;LDA CHARSTA $E02,Y;DEC CHAR;DEXBPL PRJIG1;; JSR COLJIG ;* PRINT SOME COLOUR;RTS;;;-------------------------------;;;.END